1	/**
2	 * การคำนวณระยะเวลา
3	 *
4	 * โมดูลนี้เป็นแหล่งความจริงเดียวของการแปลง "ช่วงเวลา" เป็น "จำนวนนาทีที่นับ"
5	 * ใช้ทั้งในการคิดค่าบริการ (REQ-33, REQ-35) และการนับโควตาการใช้งาน (REQ-14)
6	 */
7	
8	export const BILLING_INCREMENT_MINUTES = 15;
9	
10	/** จำนวนนาทีดิบระหว่างสองเวลา (ไม่ปัด) */
11	export function rawMinutesBetween(startIso: string, endIso: string): number {
12	  const ms = new Date(endIso).getTime() - new Date(startIso).getTime();
13	  return ms / 60000;
14	}
15	
16	/**
17	 * จำนวนนาทีที่นำไปคิดค่าบริการ — ปัดขึ้นเป็นจำนวนเท่าของ 15 นาที (REQ-35)
18	 *
19	 * ตัวอย่าง: ใช้จริง 2 ชม. 3 นาที (123 นาที) -> 135 นาที (2 ชม. 15 นาที)
20	 */
21	export function billableMinutes(startIso: string, endIso: string): number {
22	  const raw = rawMinutesBetween(startIso, endIso);
23	  if (raw <= 0) return 0;
24	  return Math.ceil(raw / BILLING_INCREMENT_MINUTES) * BILLING_INCREMENT_MINUTES;
25	}
26	
27	/** ระยะเวลาที่จองไว้ (ตามที่ขอ ไม่ใช่ที่ใช้จริง) เป็นนาที */
28	export function bookedMinutes(startAt: string, endAt: string): number {
29	  return rawMinutesBetween(startAt, endAt);
30	}
31	
32	/** ระยะเวลาที่จองไว้เป็นชั่วโมง ใช้ตรวจเพดานต่อครั้ง (REQ-10 ถึง REQ-13) */
33	export function bookedHours(startAt: string, endAt: string): number {
34	  return bookedMinutes(startAt, endAt) / 60;
35	}
