1	/**
2	 * Aggregate ของการจอง
3	 *
4	 * รับคำสั่ง -> ตรวจกฎ -> คายเหตุการณ์ออกมา
5	 * ไม่มีการเก็บสถานะไว้ที่ไหน สถานะได้จากการเล่นเหตุการณ์ซ้ำเสมอ (replay)
6	 */
7	
8	import type { BookingStatus, DomainEvent, Role } from './events.ts';
9	import { findResource, requiresApproval, OVERRUN_ALLOWANCE_MINUTES } from './policy.ts';
10	import { bookedHours } from '../lib/duration.ts';
11	import { nowIso } from '../lib/clock.ts';
12	
13	export class DomainError extends Error {
14	  code: string;
15	  httpStatus: number;
16	
17	  constructor(code: string, message: string, httpStatus: number) {
18	    super(message);
19	    this.name = 'DomainError';
20	    this.code = code;
21	    this.httpStatus = httpStatus;
22	  }
23	}
24	
25	export interface BookingState {
26	  id: string;
27	  userId: string;
28	  userRole: Role;
29	  resourceId: string;
30	  startAt: string;
31	  endAt: string;
32	  status: BookingStatus;
33	  requiresApproval: boolean;
34	  approvedBy: string | null;
35	  rejectionReason: string | null;
36	  actualStartAt: string | null;
37	  actualEndAt: string | null;
38	}
39	
40	/**
41	 * สร้างสถานะปัจจุบันจากเหตุการณ์ — หัวใจของ event sourcing
42	 * เหตุการณ์เดิม + ตรรกะที่เปลี่ยนไป = สถานะที่ต่างไป แม้ข้อมูลจะไม่ถูกแตะเลย
43	 */
44	export function replay(events: DomainEvent[]): BookingState | null {
45	  let s: BookingState | null = null;
46	  for (const e of events) {
47	    switch (e.type) {
48	      case 'BookingRequested':
49	        s = {
50	          id: e.bookingId, userId: e.userId, userRole: e.userRole, resourceId: e.resourceId,
51	          startAt: e.startAt, endAt: e.endAt, status: 'REQUESTED',
52	          requiresApproval: e.requiresApproval, approvedBy: null, rejectionReason: null,
53	          actualStartAt: null, actualEndAt: null,
54	        };
55	        break;
56	      case 'BookingApproved':
57	        if (s) { s.status = 'APPROVED'; s.approvedBy = e.actorId; }
58	        break;
59	      case 'BookingRejected':
60	        if (s) { s.status = 'REJECTED'; s.rejectionReason = e.reason; }
61	        break;
62	      case 'BookingStarted':
63	        if (s) { s.status = 'ACTIVE'; s.actualStartAt = e.actualStartAt; }
64	        break;
65	      case 'BookingCompleted':
66	        if (s) { s.status = 'COMPLETED'; s.actualEndAt = e.actualEndAt; }
67	        break;
68	    }
69	  }
70	  return s;
71	}
72	
73	/** จัดกลุ่มเหตุการณ์ตามรายการจอง แล้ว replay ทีละรายการ */
74	export function replayAll(events: DomainEvent[]): BookingState[] {
75	  const byId = new Map<string, DomainEvent[]>();
76	  for (const e of events) {
77	    if (!byId.has(e.bookingId)) byId.set(e.bookingId, []);
78	    byId.get(e.bookingId)!.push(e);
79	  }
80	  return [...byId.values()].map(replay).filter((s): s is BookingState => s !== null);
81	}
82	
83	/** สถานะที่ยังจับจองทรัพยากรอยู่ ใช้ตรวจการซ้อนทับ (REQ-05) */
84	const OCCUPYING: BookingStatus[] = ['REQUESTED', 'APPROVED', 'ACTIVE'];
85	
86	function overlaps(aStart: string, aEnd: string, bStart: string, bEnd: string): boolean {
87	  return new Date(aStart) < new Date(bEnd) && new Date(bStart) < new Date(aEnd);
88	}
89	
90	export interface CreateBookingCommand {
91	  bookingId: string;
92	  userId: string;
93	  userRole: Role;
94	  resourceId: string;
95	  startAt: string;
96	  endAt: string;
97	}
98	
99	/**
100	 * สร้างคำขอจอง
101	 *
102	 * บังคับใช้แล้ว: REQ-01, REQ-02, REQ-03, REQ-05, REQ-06, REQ-07, REQ-08, REQ-17
103	 */
104	export function createBooking(cmd: CreateBookingCommand, existing: BookingState[]): DomainEvent[] {
105	  if (!cmd.resourceId || !cmd.startAt || !cmd.endAt) {
106	    throw new DomainError('MISSING_FIELD', 'ต้องระบุ resourceId, startAt และ endAt', 400);
107	  }
108	  if (!findResource(cmd.resourceId)) {
109	    throw new DomainError('RESOURCE_NOT_FOUND', `ไม่พบเครื่อง ${cmd.resourceId}`, 404);
110	  }
111	  const now = new Date(nowIso());
112	  if (new Date(cmd.startAt) <= now) {
113	    throw new DomainError('START_IN_PAST', 'startAt ต้องเป็นเวลาในอนาคต', 400);
114	  }
115	  if (new Date(cmd.endAt) <= new Date(cmd.startAt)) {
116	    throw new DomainError('INVALID_RANGE', 'endAt ต้องอยู่หลัง startAt', 400);
117	  }
118	
119	  const clash = existing.find(
120	    (b) => b.resourceId === cmd.resourceId && OCCUPYING.includes(b.status) &&
121	           overlaps(cmd.startAt, cmd.endAt, b.startAt, b.endAt),
122	  );
123	  if (clash) {
124	    throw new DomainError('OVERLAPPING_BOOKING', `ช่วงเวลาซ้อนทับกับการจอง ${clash.id}`, 409);
125	  }
126	
127	  return [{
128	    type: 'BookingRequested',
129	    bookingId: cmd.bookingId,
130	    occurredAt: nowIso(),
131	    actorId: cmd.userId,
132	    userId: cmd.userId,
133	    userRole: cmd.userRole,
134	    resourceId: cmd.resourceId,
135	    startAt: cmd.startAt,
136	    endAt: cmd.endAt,
137	    requiresApproval: requiresApproval(bookedHours(cmd.startAt, cmd.endAt)),
138	  }];
139	}
140	
141	/** อนุมัติคำขอ — REQ-18, REQ-19, REQ-20 */
142	export function approveBooking(state: BookingState, approverId: string, approverRole: Role): DomainEvent[] {
143	  if (approverRole !== 'LAB_ADMIN') {
144	    throw new DomainError('FORBIDDEN', 'ผู้อนุมัติต้องมีบทบาท LAB_ADMIN', 403);
145	  }
146	  if (approverId === state.userId) {
147	    throw new DomainError('SELF_APPROVAL', 'ผู้ขอจองอนุมัติคำขอของตัวเองไม่ได้', 403);
148	  }
149	  if (state.status !== 'REQUESTED') {
150	    throw new DomainError('INVALID_STATE', `อนุมัติไม่ได้เมื่อสถานะเป็น ${state.status}`, 409);
151	  }
152	  return [{ type: 'BookingApproved', bookingId: state.id, occurredAt: nowIso(), actorId: approverId }];
153	}
154	
155	/** ปฏิเสธคำขอ — REQ-18, REQ-21 */
156	export function rejectBooking(state: BookingState, actorId: string, actorRole: Role, reason: string): DomainEvent[] {
157	  if (actorRole !== 'LAB_ADMIN') {
158	    throw new DomainError('FORBIDDEN', 'ผู้ปฏิเสธต้องมีบทบาท LAB_ADMIN', 403);
159	  }
160	  if (!reason || !reason.trim()) {
161	    throw new DomainError('MISSING_REASON', 'การปฏิเสธต้องระบุเหตุผล', 400);
162	  }
163	  if (state.status !== 'REQUESTED') {
164	    throw new DomainError('INVALID_STATE', `ปฏิเสธไม่ได้เมื่อสถานะเป็น ${state.status}`, 409);
165	  }
166	  return [{ type: 'BookingRejected', bookingId: state.id, occurredAt: nowIso(), actorId, reason }];
167	}
168	
169	/** เริ่มใช้งานจริง — REQ-23, REQ-29 (การจองเกินเกณฑ์ต้องผ่านการอนุมัติก่อน ตาม REQ-17) */
170	export function startBooking(state: BookingState, actorId: string): DomainEvent[] {
171	  if (state.requiresApproval && state.status !== 'APPROVED') {
172	    throw new DomainError('APPROVAL_REQUIRED', 'การจองนี้ต้องได้รับอนุมัติก่อนเริ่มใช้งาน', 409);
173	  }
174	  if (!state.requiresApproval && !['REQUESTED', 'APPROVED'].includes(state.status)) {
175	    throw new DomainError('INVALID_STATE', `เริ่มใช้งานไม่ได้เมื่อสถานะเป็น ${state.status}`, 409);
176	  }
177	  if (state.status === 'ACTIVE') {
178	    throw new DomainError('INVALID_STATE', 'เริ่มใช้งานไปแล้ว', 409);
179	  }
180	  return [{ type: 'BookingStarted', bookingId: state.id, occurredAt: nowIso(), actorId, actualStartAt: nowIso() }];
181	}
182	
183	/** สิ้นสุดการใช้งาน — REQ-31, REQ-32 */
184	export function completeBooking(state: BookingState, actorId: string): DomainEvent[] {
185	  if (state.status !== 'ACTIVE') {
186	    throw new DomainError('INVALID_STATE', `สิ้นสุดการใช้งานไม่ได้เมื่อสถานะเป็น ${state.status}`, 409);
187	  }
188	  const limit = new Date(new Date(state.endAt).getTime() + OVERRUN_ALLOWANCE_MINUTES * 60000);
189	  const actual = new Date(nowIso());
190	  const actualEndAt = (actual > limit ? limit : actual).toISOString();
