1	/**
2	 * นิยามเหตุการณ์ทั้งหมดของโดเมน
3	 *
4	 * เหตุการณ์คือสิ่งที่ "เกิดขึ้นแล้ว" จึงตั้งชื่อเป็นอดีตกาลเสมอ
5	 * เมื่อบันทึกแล้วห้ามแก้ไขหรือลบ (REQ-40) การเปลี่ยนแปลงทำได้เฉพาะการเพิ่มเหตุการณ์ใหม่ต่อท้าย
6	 */
7	
8	export type BookingStatus =
9	  | 'REQUESTED' | 'APPROVED' | 'REJECTED'
10	  | 'ACTIVE' | 'COMPLETED' | 'CANCELLED' | 'NO_SHOW';
11	
12	export type Role = 'STUDENT' | 'PHD_STUDENT' | 'LECTURER' | 'LAB_ADMIN';
13	
14	interface EventBase {
15	  bookingId: string;
16	  /** เวลาที่เหตุการณ์เกิดขึ้น (REQ-39) */
17	  occurredAt: string;
18	  /** ผู้ที่ทำให้เหตุการณ์นี้เกิด (REQ-39) */
19	  actorId: string;
20	}
21	
22	export interface BookingRequested extends EventBase {
23	  type: 'BookingRequested';
24	  userId: string;
25	  userRole: Role;
26	  resourceId: string;
27	  startAt: string;
28	  endAt: string;
29	  requiresApproval: boolean;
30	}
31	
32	export interface BookingApproved extends EventBase {
33	  type: 'BookingApproved';
34	}
35	
36	export interface BookingRejected extends EventBase {
37	  type: 'BookingRejected';
38	  reason: string;
39	}
40	
