/**
 * การคำนวณสัปดาห์สำหรับโควตารายสัปดาห์ (REQ-14)
 *
 * สัปดาห์เริ่มวันจันทร์ เวลา 00:00 ตามเวลาไทย (UTC+7) — REQ-15
 * ใช้ offset ตายตัวแทนการอิงเขตเวลาของเครื่องที่รันเซิร์ฟเวอร์ เพื่อให้ผลลัพธ์คงที่ไม่ว่าจะรันที่ไหน
 */

const LOCAL_OFFSET_MINUTES = 7 * 60;
const DAY_MS = 24 * 60 * 60 * 1000;

/** จุดเริ่มต้น (วันจันทร์ 00:00 เวลาไทย) ของสัปดาห์ที่ครอบคลุมเวลาที่ให้มา */
export function weekStart(iso: string): Date {
  const local = new Date(new Date(iso).getTime() + LOCAL_OFFSET_MINUTES * 60000);
  const dayIndex = (local.getUTCDay() + 6) % 7; // จันทร์ = 0 ... อาทิตย์ = 6
  const localMonday = Date.UTC(local.getUTCFullYear(), local.getUTCMonth(), local.getUTCDate()) - dayIndex * DAY_MS;
  return new Date(localMonday - LOCAL_OFFSET_MINUTES * 60000);
}

/** สองเวลาตกอยู่ในสัปดาห์เดียวกันหรือไม่ (REQ-15) */
export function isSameWeek(aIso: string, bIso: string): boolean {
  return weekStart(aIso).getTime() === weekStart(bIso).getTime();
}

